from pathlib import Path
p=Path('/mnt/data/mawiz_frontend_build')

# models
f=p/'app/models.py'; s=f.read_text()
append='''\n\nclass Referral(db.Model):\n    id = db.Column(db.Integer, primary_key=True)\n    referrer_id = db.Column(db.Integer, db.ForeignKey("user.id", ondelete="CASCADE"), nullable=False, index=True)\n    referred_user_id = db.Column(db.Integer, db.ForeignKey("user.id", ondelete="SET NULL"), nullable=True, index=True)\n    code = db.Column(db.String(32), nullable=False, index=True)\n    status = db.Column(db.String(30), nullable=False, default="pending", index=True)\n    reward_value = db.Column(db.Numeric(12, 2), default=0)\n    created_at = db.Column(db.DateTime, default=lambda: datetime.now(timezone.utc), nullable=False)\n    completed_at = db.Column(db.DateTime)\n\n\nclass Coupon(db.Model):\n    id = db.Column(db.Integer, primary_key=True)\n    code = db.Column(db.String(64), unique=True, nullable=False, index=True)\n    description = db.Column(db.String(255), default="")\n    discount_type = db.Column(db.String(20), nullable=False, default="percent")\n    discount_value = db.Column(db.Numeric(12, 2), nullable=False, default=0)\n    minimum_amount = db.Column(db.Numeric(12, 2), nullable=False, default=0)\n    max_redemptions = db.Column(db.Integer)\n    per_user_limit = db.Column(db.Integer, nullable=False, default=1)\n    starts_at = db.Column(db.DateTime)\n    expires_at = db.Column(db.DateTime)\n    active = db.Column(db.Boolean, nullable=False, default=True, index=True)\n    created_at = db.Column(db.DateTime, default=lambda: datetime.now(timezone.utc), nullable=False)\n    redemptions = db.relationship("CouponRedemption", backref="coupon", cascade="all, delete-orphan")\n\n\nclass CouponRedemption(db.Model):\n    id = db.Column(db.Integer, primary_key=True)\n    coupon_id = db.Column(db.Integer, db.ForeignKey("coupon.id", ondelete="CASCADE"), nullable=False, index=True)\n    user_id = db.Column(db.Integer, db.ForeignKey("user.id", ondelete="CASCADE"), nullable=False, index=True)\n    course_id = db.Column(db.Integer, db.ForeignKey("course.id", ondelete="SET NULL"), nullable=True)\n    amount_before = db.Column(db.Numeric(12, 2), nullable=False, default=0)\n    discount_amount = db.Column(db.Numeric(12, 2), nullable=False, default=0)\n    amount_after = db.Column(db.Numeric(12, 2), nullable=False, default=0)\n    status = db.Column(db.String(20), nullable=False, default="applied")\n    created_at = db.Column(db.DateTime, default=lambda: datetime.now(timezone.utc), nullable=False)\n'''
if 'class Referral(db.Model)' not in s: f.write_text(s+append)

# main routes search + referrals learner page
f=p/'app/main/routes.py'; s=f.read_text()
s='''from flask import Blueprint, render_template, request, abort\nfrom app.common.security import current_user\nfrom app.models import User, Course, Project, Simulation, AuditEvent, Referral, Coupon\n\nmain_bp = Blueprint("main", __name__)\n\n@main_bp.route("/")\ndef home(): return render_template("main/home.html")\n\n@main_bp.route("/about")\ndef about(): return render_template("main/simple.html", title="About Mawiz", body="Mawiz helps learners learn skills, experience work and prove capability.")\n\n@main_bp.route("/search")\ndef search():\n    user = current_user()\n    if not user:\n        abort(403)\n    q = request.args.get("q", "").strip()[:100]\n    results = {"users": [], "courses": [], "projects": [], "simulations": [], "coupons": [], "referrals": []}\n    if q:\n        like = f"%{q}%"\n        results["courses"] = Course.query.filter((Course.title.ilike(like)) | (Course.description.ilike(like))).limit(8).all()\n        results["projects"] = Project.query.filter((Project.title.ilike(like)) | (Project.problem.ilike(like))).limit(8).all()\n        results["simulations"] = Simulation.query.filter((Simulation.title.ilike(like)) | (Simulation.scenario.ilike(like))).limit(8).all()\n        if user.role == "admin":\n            results["users"] = User.query.filter((User.email.ilike(like))).limit(8).all()\n            results["coupons"] = Coupon.query.filter(Coupon.code.ilike(like)).limit(8).all()\n            results["referrals"] = Referral.query.filter(Referral.code.ilike(like)).limit(8).all()\n    return render_template("main/search.html", q=q, results=results)\n'''
f.write_text(s)

# admin imports and routes append
f=p/'app/admin/routes.py'; s=f.read_text()
s=s.replace('    SimulationAttempt, AuditEvent\n)', '    SimulationAttempt, AuditEvent, Referral, Coupon, CouponRedemption\n)')
append='''\n\n@admin_bp.route("/referrals")\n@permission_required("admin.dashboard.view", "admin")\ndef referrals():\n    rows = Referral.query.order_by(Referral.created_at.desc()).limit(200).all()\n    user_ids = {x.referrer_id for x in rows} | {x.referred_user_id for x in rows if x.referred_user_id}\n    users = {u.id: u for u in User.query.filter(User.id.in_(user_ids)).all()} if user_ids else {}\n    return render_template("admin/referrals.html", referrals=rows, users=users)\n\n\n@admin_bp.route("/referrals/create", methods=["POST"])\n@permission_required("admin.dashboard.view", "admin")\ndef create_referral_code():\n    user_id = _safe_int(request.form.get("user_id"), minimum=1)\n    user = db.session.get(User, user_id)\n    if not user:\n        flash("User not found.", "error")\n        return redirect(url_for("admin.referrals"))\n    code = re.sub(r"[^A-Z0-9]", "", request.form.get("code", "").upper())[:32] or f"MAWIZ{user.id:04d}"\n    if Referral.query.filter_by(code=code).first():\n        flash("That referral code already exists.", "error")\n        return redirect(url_for("admin.referrals"))\n    db.session.add(Referral(referrer_id=user.id, code=code, status="active"))\n    audit("admin.referral_code_created")\n    db.session.commit()\n    flash("Referral code created.", "success")\n    return redirect(url_for("admin.referrals"))\n\n\n@admin_bp.route("/coupons", methods=["GET", "POST"])\n@permission_required("admin.dashboard.view", "admin")\ndef coupons():\n    if request.method == "POST":\n        code = re.sub(r"[^A-Z0-9_-]", "", request.form.get("code", "").upper())[:64]\n        if not code:\n            flash("Coupon code is required.", "error")\n        elif Coupon.query.filter_by(code=code).first():\n            flash("That coupon code already exists.", "error")\n        else:\n            coupon = Coupon(code=code, description=request.form.get("description", "").strip()[:255],\n                discount_type=request.form.get("discount_type", "percent") if request.form.get("discount_type") in {"percent", "fixed"} else "percent",\n                discount_value=_safe_int(request.form.get("discount_value"), 0, 0, 100000000),\n                minimum_amount=_safe_int(request.form.get("minimum_amount"), 0, 0, 100000000),\n                max_redemptions=_safe_int(request.form.get("max_redemptions"), 0, 0, 100000000) or None,\n                per_user_limit=_safe_int(request.form.get("per_user_limit"), 1, 1, 100), active=True)\n            db.session.add(coupon); audit("admin.coupon_created"); db.session.commit(); flash("Coupon created.", "success")\n    rows = Coupon.query.order_by(Coupon.created_at.desc()).all()\n    redemption_counts = {c.id: CouponRedemption.query.filter_by(coupon_id=c.id, status="applied").count() for c in rows}\n    return render_template("admin/coupons.html", coupons=rows, redemption_counts=redemption_counts)\n\n\n@admin_bp.post("/coupons/<int:coupon_id>/toggle")\n@permission_required("admin.dashboard.view", "admin")\ndef toggle_coupon(coupon_id):\n    coupon = Coupon.query.get_or_404(coupon_id); coupon.active = not coupon.active\n    audit("admin.coupon_enabled" if coupon.active else "admin.coupon_disabled"); db.session.commit()\n    flash("Coupon status updated.", "success"); return redirect(url_for("admin.coupons"))\n\n\n@admin_bp.route("/coupon/validate", methods=["POST"])\n@permission_required("learning.catalog.view", "learner", "instructor", "mentor", "admin")\ndef validate_coupon():\n    from datetime import datetime, timezone\n    code = re.sub(r"[^A-Z0-9_-]", "", request.form.get("code", "").upper())\n    amount = float(request.form.get("amount", "0") or 0)\n    coupon = Coupon.query.filter_by(code=code, active=True).first()\n    now = datetime.now(timezone.utc).replace(tzinfo=None)\n    if not coupon or (coupon.starts_at and coupon.starts_at > now) or (coupon.expires_at and coupon.expires_at < now):\n        return {"valid": False, "message": "Coupon is invalid or expired."}, 400\n    if amount < float(coupon.minimum_amount or 0):\n        return {"valid": False, "message": "Minimum amount not met."}, 400\n    total = CouponRedemption.query.filter_by(coupon_id=coupon.id, status="applied").count()\n    mine = CouponRedemption.query.filter_by(coupon_id=coupon.id, user_id=current_user().id, status="applied").count()\n    if coupon.max_redemptions and total >= coupon.max_redemptions: return {"valid": False, "message": "Coupon redemption limit reached."}, 400\n    if mine >= coupon.per_user_limit: return {"valid": False, "message": "You have already used this coupon."}, 400\n    discount = amount * float(coupon.discount_value) / 100 if coupon.discount_type == "percent" else min(amount, float(coupon.discount_value))\n    return {"valid": True, "code": coupon.code, "discount": round(discount, 2), "amount_after": round(amount-discount, 2)}\n'''
if 'def referrals()' not in s: f.write_text(s+append)

# auth referral capture
f=p/'app/auth/routes.py'; s=f.read_text()
s=s.replace('from app.models import User, Profile, EmailAuthChallenge', 'from app.models import User, Profile, EmailAuthChallenge, Referral')
s=s.replace('    if request.method == "POST":\n        email = request.form.get("email", "").strip().lower()', '    if request.method == "POST":\n        email = request.form.get("email", "").strip().lower()', 1)
s=s.replace('        db.session.add(user)\n        db.session.flush()\n        verify_link', '        db.session.add(user)\n        db.session.flush()\n        referral_code = request.form.get("referral_code", "").strip().upper()[:32]\n        if referral_code:\n            referral = Referral.query.filter_by(code=referral_code, status="active").first()\n            if referral and referral.referrer_id != user.id and referral.referred_user_id is None:\n                referral.referred_user_id = user.id\n                referral.status = "completed"\n                referral.completed_at = datetime.now(timezone.utc)\n                audit("referral.completed")\n        verify_link', 1)
f.write_text(s)

