(p/'app/templates/main/search.html').write_text('''{% extends 'base.html' %}\n{% block title %}Search — Mawiz{% endblock %}\n{% block content %}<section class="page search-page"><span class="eyebrow">GLOBAL SEARCH</span><h1>Search Mawiz</h1><form class="search-page-form" method="get"><input name="q" value="{{ q }}" placeholder="Search courses, projects, simulations{% if current_user.role == 'admin' %}, users, coupons...{% endif %}" autofocus><button class="button" type="submit">Search</button></form>{% if q %}<div class="search-results">{% for kind,items in results.items() if items %}<section class="panel"><div class="panel-head"><h2>{{ kind|replace('_',' ')|title }}</h2><span class="tag">{{ items|length }} results</span></div>{% for item in items %}<a class="search-result" href="{% if kind=='courses' %}{{ url_for('learning.course_detail', slug=item.slug) }}{% elif kind=='projects' %}{{ url_for('projects.detail', project_id=item.id) }}{% elif kind=='simulations' %}{{ url_for('simulations.detail', simulation_id=item.id) }}{% elif kind=='users' %}{{ url_for('admin.user_detail', user_id=item.id) }}{% else %}{{ url_for('admin.coupons') if kind=='coupons' else url_for('admin.referrals') }}{% endif %}"><div><strong>{% if kind=='users' %}{{ item.profile.first_name ~ ' ' ~ item.profile.last_name if item.profile else item.email }}{% elif kind in ('coupons','referrals') %}{{ item.code }}{% else %}{{ item.title }}{% endif %}</strong><span>{% if kind=='courses' %}{{ item.description[:140] }}{% elif kind=='projects' %}{{ item.problem[:140] }}{% elif kind=='simulations' %}{{ item.scenario[:140] }}{% elif kind=='users' %}{{ item.email }}{% else %}Management record{% endif %}</span></div><b>→</b></a>{% endfor %}</section>{% else %}<div class="panel empty">No matching entities found. Try another search.</div>{% endfor %}</div>{% else %}<div class="panel search-empty"><h2>Search across your Mawiz workspace</h2><p>Find learning paths, practical projects, simulations and{% if current_user.role == 'admin' %} administrative records{% endif %} from one place.</p></div>{% endif %}</section>{% endblock %}''')

(p/'app/templates/admin/referrals.html').write_text('''{% extends 'base.html' %}{% block title %}Referrals — Admin{% endblock %}{% block content %}<section class="page admin-page"><div class="admin-hero"><div><span class="eyebrow">GROWTH</span><h1>Referrals</h1><p>Manage referral codes and track referred learners.</p></div></div><div class="admin-grid"><section class="panel"><div class="panel-head"><h2>Create referral code</h2></div><form method="post" action="{{ url_for('admin.create_referral_code') }}"><label>User ID<input name="user_id" type="number" min="1" required></label><label>Code <small>Optional; auto-generated if empty.</small><input name="code" placeholder="MAWIZFRIEND"></label><button class="button">Create code</button></form></section><section class="panel"><h2>Program snapshot</h2><div class="mini-metrics"><div><b>{{ referrals|length }}</b><span>recent referrals</span></div><div><b>{{ referrals|selectattr('status','equalto','completed')|list|length }}</b><span>completed</span></div></div></section></div><section class="panel table-panel"><table class="data-table"><thead><tr><th>Code</th><th>Referrer</th><th>Referred learner</th><th>Status</th><th>Created</th></tr></thead><tbody>{% for r in referrals %}<tr><td><strong>{{ r.code }}</strong></td><td>{{ users[r.referrer_id].email if r.referrer_id in users else '—' }}</td><td>{{ users[r.referred_user_id].email if r.referred_user_id in users else 'Waiting' }}</td><td><span class="status status-{{ r.status }}">{{ r.status }}</span></td><td>{{ r.created_at.strftime('%Y-%m-%d') }}</td></tr>{% else %}<tr><td colspan="5" class="empty">No referral activity yet.</td></tr>{% endfor %}</tbody></table></section></section>{% endblock %}''')

(p/'app/templates/admin/coupons.html').write_text('''{% extends 'base.html' %}{% block title %}Coupons — Admin{% endblock %}{% block content %}<section class="page admin-page"><div class="admin-hero"><div><span class="eyebrow">GROWTH</span><h1>Coupons</h1><p>Create and control promotional offers with redemption limits.</p></div></div><section class="panel"><h2>Create coupon</h2><form method="post" class="grid2"><label>Code<input name="code" placeholder="WELCOME20" required></label><label>Description<input name="description" placeholder="New learner offer"></label><label>Discount type<select name="discount_type"><option value="percent">Percentage</option><option value="fixed">Fixed amount</option></select></label><label>Discount value<input name="discount_value" type="number" min="0" step="0.01" required></label><label>Minimum amount<input name="minimum_amount" type="number" min="0" step="0.01" value="0"></label><label>Max redemptions<input name="max_redemptions" type="number" min="0" placeholder="Unlimited"></label><label>Per-user limit<input name="per_user_limit" type="number" min="1" value="1"></label><div style="align-self:end"><button class="button">Create coupon</button></div></form></section><section class="panel table-panel"><table class="data-table"><thead><tr><th>Code</th><th>Offer</th><th>Limit</th><th>Used</th><th>Status</th><th></th></tr></thead><tbody>{% for c in coupons %}<tr><td><strong>{{ c.code }}</strong><small>{{ c.description }}</small></td><td>{{ c.discount_value }}{% if c.discount_type=='percent' %}%{% else %} fixed{% endif %}</td><td>{{ c.max_redemptions or 'Unlimited' }}</td><td>{{ redemption_counts[c.id] }}</td><td><span class="status {{ 'status-approved' if c.active else 'status-rejected' }}">{{ 'active' if c.active else 'disabled' }}</span></td><td><form method="post" action="{{ url_for('admin.toggle_coupon', coupon_id=c.id) }}"><button class="link-button">{{ 'Disable' if c.active else 'Enable' }}</button></form></td></tr>{% else %}<tr><td colspan="6" class="empty">No coupons created yet.</td></tr>{% endfor %}</tbody></table></section></section>{% endblock %}''')

